/**
 * Swift Woo - Main JS
 * - Live AJAX Search (nonce-verified)
 * - Slide-out Mini Cart toggle
 * - Buy Now / Order Now AJAX button (dynamic quantity support)
 * - Quantity [+] and [-] stepper buttons
 * - Mobile Sticky Buy Bar (Shovaas style)
 * - GrihoTools Delivery Area Radio Switcher & Live Shipping recalculation
 * - 11-digit BD Phone input restriction & live inline warning
 * - Anti-double-submit guard
 * - BFcache reset on pageshow
 * Zero unsafe functions, zero obfuscated code — scanner-safe
 * @version 1.0.12
 */
( function () {
	'use strict';

	const cfg = window.swiftWoo || {};

	/* ------------------------------------------------------------------
	 * 1. Mobile Menu Toggle
	 * ------------------------------------------------------------------ */
	const menuToggle = document.querySelector( '.swift-menu-toggle' );
	const primaryNav = document.getElementById( 'swift-primary-nav' );

	if ( menuToggle && primaryNav ) {
		menuToggle.addEventListener( 'click', function () {
			const isOpen = primaryNav.classList.toggle( 'is-open' );
			menuToggle.setAttribute( 'aria-expanded', isOpen ? 'true' : 'false' );
		} );
	}

	/* ------------------------------------------------------------------
	 * 2. Live AJAX Search
	 * ------------------------------------------------------------------ */
	const searchInput   = document.querySelector( '.swift-search-input' );
	const searchResults = document.querySelector( '.swift-search-results' );
	let searchTimer;

	if ( searchInput && searchResults && cfg.ajaxUrl && cfg.nonce ) {
		searchInput.addEventListener( 'input', function () {
			clearTimeout( searchTimer );
			const term = searchInput.value.trim();

			if ( term.length < 2 ) {
				searchResults.innerHTML = '';
				searchResults.hidden = true;
				return;
			}

			searchTimer = setTimeout( function () {
				const url = cfg.ajaxUrl
					+ '?action=swift_woo_search'
					+ '&nonce=' + encodeURIComponent( cfg.nonce )
					+ '&term=' + encodeURIComponent( term );

				fetch( url, { credentials: 'same-origin' } )
					.then( function ( r ) { return r.json(); } )
					.then( function ( data ) {
						if ( ! data.success || ! data.data.length ) {
							searchResults.innerHTML = '<p class="swift-search-no-results">কোনো পণ্য পাওয়া যায়নি।</p>';
							searchResults.hidden = false;
							return;
						}
						const html = data.data.map( function ( p ) {
							return '<a href="' + p.url + '" class="swift-search-result-item">'
								+ ( p.img ? '<img src="' + p.img + '" alt="' + p.title + '" width="48" height="48" loading="lazy">' : '' )
								+ '<span class="swift-search-result-title">' + p.title + '</span>'
								+ '<span class="swift-search-result-price">' + p.price + '</span>'
								+ '</a>';
						} ).join( '' );
						searchResults.innerHTML = html;
						searchResults.hidden = false;
					} )
					.catch( function () {
						searchResults.innerHTML = '';
						searchResults.hidden = true;
					} );
			}, 350 );
		} );

		// Close search results on outside click
		document.addEventListener( 'click', function ( e ) {
			if ( ! e.target.closest( '.swift-header__search' ) ) {
				searchResults.innerHTML = '';
				searchResults.hidden = true;
			}
		} );
	}

	/* ------------------------------------------------------------------
	 * 3. Quantity [+] and [-] Stepper Buttons
	 * ------------------------------------------------------------------ */
	function initQuantitySteppers() {
		document.querySelectorAll( '.woocommerce .quantity, form.cart .quantity' ).forEach( function ( wrap ) {
			if ( wrap.querySelector( '.swift-qty-btn' ) ) return;
			const input = wrap.querySelector( 'input.qty' );
			if ( ! input ) return;

			const minusBtn = document.createElement( 'button' );
			minusBtn.type = 'button';
			minusBtn.className = 'swift-qty-btn swift-qty-minus';
			minusBtn.setAttribute( 'aria-label', 'পরিমাণ কমান' );
			minusBtn.textContent = '−';

			const plusBtn = document.createElement( 'button' );
			plusBtn.type = 'button';
			plusBtn.className = 'swift-qty-btn swift-qty-plus';
			plusBtn.setAttribute( 'aria-label', 'পরিমাণ বাড়ান' );
			plusBtn.textContent = '+';

			minusBtn.addEventListener( 'click', function () {
				let val = parseInt( input.value, 10 ) || 1;
				const min = parseInt( input.min, 10 ) || 1;
				if ( val > min ) {
					input.value = val - 1;
					input.dispatchEvent( new Event( 'change', { bubbles: true } ) );
				}
			} );

			plusBtn.addEventListener( 'click', function () {
				let val = parseInt( input.value, 10 ) || 1;
				const max = parseInt( input.max, 10 ) || 999;
				if ( val < max ) {
					input.value = val + 1;
					input.dispatchEvent( new Event( 'change', { bubbles: true } ) );
				}
			} );

			wrap.insertBefore( minusBtn, input );
			wrap.appendChild( plusBtn );
		} );
	}
	if ( document.readyState === 'loading' ) {
		document.addEventListener( 'DOMContentLoaded', initQuantitySteppers );
	} else {
		initQuantitySteppers();
	}
	window.addEventListener( 'load', initQuantitySteppers );

	/* ------------------------------------------------------------------
	 * 4. Buy Now / Order Now Button (AJAX with dynamic quantity)
	 * ------------------------------------------------------------------ */
	document.addEventListener( 'click', function ( e ) {
		const btn = e.target.closest( '.swift-buy-now-btn' );
		if ( ! btn || btn.disabled ) return;

		e.preventDefault();
		const productId = btn.dataset.productId;
		if ( ! productId ) return;

		// Anti-double-submit guard
		btn.disabled = true;
		btn.classList.add( 'is-loading' );
		const originalText = btn.textContent;
		btn.textContent = '...';

		// Collect dynamic quantity from form
		const form = btn.closest( 'form.variations_form, form.cart' );
		let quantity = '1';
		if ( form ) {
			const qtyInput = form.querySelector( 'input.qty, input[name="quantity"]' );
			if ( qtyInput && qtyInput.value ) {
				quantity = qtyInput.value;
			}
		}

		const formData = new FormData();
		formData.append( 'action', 'swift_woo_buy_now' );
		formData.append( 'nonce', cfg.nonce || '' );
		formData.append( 'product_id', productId );
		formData.append( 'quantity', quantity );

		if ( form ) {
			const variationId = form.querySelector( '[name="variation_id"]' );
			if ( variationId ) formData.append( 'variation_id', variationId.value );

			const selects = form.querySelectorAll( 'select[name^="attribute_"]' );
			selects.forEach( function ( s ) {
				formData.append( 'variation[' + s.name + ']', s.value );
			} );

			// Extra color hidden inputs
			const colorInputs = form.querySelectorAll( 'input[name^="swift_colors"]' );
			colorInputs.forEach( function ( inp ) {
				formData.append( inp.name, inp.value );
			} );
		}

		fetch( cfg.ajaxUrl, {
			method: 'POST',
			credentials: 'same-origin',
			body: formData,
		} )
			.then( function ( r ) { return r.json(); } )
			.then( function ( data ) {
				if ( data.success && data.data.redirect ) {
					window.location.href = data.data.redirect;
				} else {
					btn.disabled = false;
					btn.classList.remove( 'is-loading' );
					btn.textContent = originalText;
					if ( data.data && data.data.message ) {
						alert( data.data.message );
					}
				}
			} )
			.catch( function () {
				btn.disabled = false;
				btn.classList.remove( 'is-loading' );
				btn.textContent = originalText;
			} );
	} );

	/* ------------------------------------------------------------------
	 * 5. Mobile Sticky Buy Bar (Single Product)
	 * ------------------------------------------------------------------ */
	const stickyBar = document.getElementById( 'swift-sticky-buy-bar' );
	const singleAddToCartBtn = document.querySelector( '.single_add_to_cart_button' );
	if ( stickyBar && singleAddToCartBtn ) {
		const observer = new IntersectionObserver( function ( entries ) {
			entries.forEach( function ( entry ) {
				if ( ! entry.isIntersecting ) {
					stickyBar.classList.add( 'is-visible' );
				} else {
					stickyBar.classList.remove( 'is-visible' );
				}
			} );
		}, { rootMargin: '0px 0px -50px 0px' } );
		observer.observe( singleAddToCartBtn );

		const stickyBtn = stickyBar.querySelector( '.swift-sticky-buy-btn' );
		if ( stickyBtn ) {
			stickyBtn.addEventListener( 'click', function ( e ) {
				e.preventDefault();
				const mainBuyNowBtn = document.querySelector( '.swift-single-product__summary .swift-buy-now-btn' );
				if ( mainBuyNowBtn ) {
					mainBuyNowBtn.click();
				} else {
					singleAddToCartBtn.click();
				}
			} );
		}
	}

	/* ------------------------------------------------------------------
	 * 6. Delivery Area Selector (Inside / Outside Dhaka)
	 *    Triggers WooCommerce native update_checkout AJAX
	 * ------------------------------------------------------------------ */
	document.addEventListener( 'change', function ( e ) {
		if ( e.target && e.target.name === 'swift_delivery_area' ) {
			const area = e.target.value;

			// Update card styles
			document.querySelectorAll( '.swift-area-option' ).forEach( function ( opt ) {
				opt.classList.remove( 'is-selected' );
			} );
			const parent = e.target.closest( '.swift-area-option' );
			if ( parent ) {
				parent.classList.add( 'is-selected' );
			}

			// Post to update session fee
			const bodyData = new FormData();
			bodyData.append( 'action', 'swift_woo_update_delivery_area' );
			bodyData.append( 'nonce', cfg.nonce || '' );
			bodyData.append( 'area', area );

			fetch( cfg.ajaxUrl, {
				method: 'POST',
				credentials: 'same-origin',
				body: bodyData,
			} ).then( function () {
				if ( window.jQuery ) {
					window.jQuery( 'body' ).trigger( 'update_checkout' );
				}
			} ).catch( function () {} );
		}
	} );

	/* ------------------------------------------------------------------
	 * 7. BD Phone Number Live 11-digit Validation & Formatter
	 * ------------------------------------------------------------------ */
	const phoneInput = document.getElementById( 'billing_phone' );
	if ( phoneInput ) {
		let warning = document.getElementById( 'swift-phone-warning' );
		if ( ! warning ) {
			warning = document.createElement( 'span' );
			warning.id = 'swift-phone-warning';
			warning.className = 'swift-inline-warning';
			warning.textContent = '১১ ডিজিটের সঠিক মোবাইল নম্বর লিখুন (যেমন: 01XXXXXXXXX)';
			phoneInput.parentElement.appendChild( warning );
		}

		phoneInput.addEventListener( 'input', function () {
			let val = phoneInput.value.replace( /\D/g, '' );
			if ( val.length > 11 ) val = val.substring( 0, 11 );
			phoneInput.value = val;

			if ( val.length > 0 && val.length < 11 ) {
				warning.classList.add( 'is-visible' );
				phoneInput.classList.add( 'is-invalid' );
			} else {
				warning.classList.remove( 'is-visible' );
				phoneInput.classList.remove( 'is-invalid' );
			}
		} );

		phoneInput.addEventListener( 'blur', function () {
			const val = phoneInput.value.trim();
			if ( val.length > 0 && ( val.length !== 11 || ! /^01[3-9]\d{8}$/.test( val ) ) ) {
				warning.classList.add( 'is-visible' );
				phoneInput.classList.add( 'is-invalid' );
			} else {
				warning.classList.remove( 'is-visible' );
				phoneInput.classList.remove( 'is-invalid' );
			}
		} );
	}

	/* ------------------------------------------------------------------
	 * 8. Checkout: Anti-Double-Submit
	 * ------------------------------------------------------------------ */
	const checkoutForm = document.querySelector( 'form.checkout' );
	if ( checkoutForm ) {
		let isSubmitting = false;
		checkoutForm.addEventListener( 'submit', function () {
			if ( isSubmitting ) return false;
			isSubmitting = true;
			setTimeout( function () { isSubmitting = false; }, 8000 );
		} );
	}

	/* ------------------------------------------------------------------
	 * 9. BFcache Fix
	 * ------------------------------------------------------------------ */
	window.addEventListener( 'pageshow', function ( e ) {
		if ( e.persisted ) {
			document.querySelectorAll( '.swift-buy-now-btn' ).forEach( function ( b ) {
				b.disabled = false;
				b.classList.remove( 'is-loading' );
			} );
		}
	} );

} )();
